355	export class Gradio<T extends object = {}, U extends object = {}> {
356		load_component: load_component;
357		shared: SharedProps = $state<SharedProps>({} as SharedProps) as SharedProps;
358		props = $state<U>({} as U) as U;
359		i18n: I18nFormatter = $state<any>((v: string) => v) as any;
360		translatable_props: Record<string, string> = {};
361		dispatcher!: Function;
362		last_update: ReturnType<typeof tick> | null = null;
363		shared_props: (keyof SharedProps)[] = allowed_shared_props;
364		mounted: boolean = false;
365		old_value: any;
366		register_component!: (
367			id: number,
368			set_data: (data: Record<string, any> & SharedProps) => void,
369			get_data: Function
370		) => void;
371	
372		constructor(
373			_props: { shared_props: SharedProps; props: U },
374			default_values?: Partial<U>
375		) {
376			for (const key in _props.shared_props) {
377				// @ts-ignore i'm not doing pointless typescript gymanstics
378				this.shared[key] = _props.shared_props[key];
379			}
380			for (const key in _props.props) {
381				// @ts-ignore same here
382				this.props[key] = _props.props[key];
383			}
384	
385			if (default_values) {
386				for (const key in default_values) {
387					if (this.props[key as keyof U] === undefined) {
388						// @ts-ignore
389						this.props[key] = default_values[key as keyof U];
390					}
391				}
392			}
393			// @ts-ignore same here
394			this.i18n = this.props.i18n ?? ((v: string) => v);
395	
396			for (const key of TRANSLATABLE_PROPS) {
397				// @ts-ignore
398				this.shared[key] = this._translate_and_store(
399					"shared",
400					key,
401					// @ts-ignore
402					_props.shared_props[key]
403				);
404				// @ts-ignore
405				this.props[key] = this._translate_and_store(
406					"props",
407					key,
408					// @ts-ignore
409					_props.props[key]
410				);
411			}
412	
413			this.load_component = this.shared.load_component;
414	
415			this.register_component = this.shared.register_component || (() => {});
416			this.dispatcher = this.shared.dispatcher || (() => {});
417	
418			this.register_component(
419				_props.shared_props.id,
420				// @ts-ignore
421				this.set_data.bind(this),
422				this.get_data.bind(this)
423			);
424	
425			$effect(() => {
426				// Need to update the props here
427				// otherwise UI won't reflect latest state from render
428				for (const key in _props.shared_props) {
429					// @ts-ignore
430					if (this._is_i18n_managed(`shared.${key}`, _props.shared_props[key]))
431						continue;
432					// @ts-ignore i'm not doing pointless typescript gymanstics
433					this.shared[key] = _props.shared_props[key];
434				}
435				for (const key in _props.props) {
436					if (this._is_i18n_managed(`props.${key}`, _props.props[key])) continue;
437					// @ts-ignore same here
438					this.props[key] = _props.props[key];
439				}
440				this.register_component(
441					_props.shared_props.id,
442					// @ts-ignore
443					this.set_data.bind(this),
444					this.get_data.bind(this)
445				);
446				untrack(() => {
447					this.shared.id = _props.shared_props.id;
448				});
449			});
450	
451			// retranslate props when locale changes
452			if (Object.keys(this.translatable_props).length > 0) {
453				locale.subscribe(() => {
454					for (const [full_key, original] of Object.entries(
455						this.translatable_props
456					)) {
457						const [target, key] = full_key.split(".");
458						const translated = this.i18n(original);
459						// @ts-ignore
460						if (target === "shared") this.shared[key] = translated;
461						// @ts-ignore
462						else this.props[key] = translated;
463					}
464				});
465			}
466		}
467	
468		// check if props are translatable
469		_is_i18n_managed(key: string, new_value: unknown): boolean {
470			const original_marker = this.translatable_props[key];
471			if (!original_marker) return false;
472			if (new_value === original_marker) return true;
473			// if value has changed then remove key
474			delete this.translatable_props[key];
475			return false;
476		}
477	
478		_translate_and_store(
479			target: "shared" | "props",
480			key: string,
481			value: unknown
482		): unknown {
483			if (typeof value !== "string") return value;
484			const translated = this.i18n(value);
485			if (translated !== value) {
486				this.translatable_props[`${target}.${key}`] = value;
487			}
488			return translated;
489		}
490	
491		dispatch<E extends keyof T>(event_name: E, data?: T[E]): void {
492			this.dispatcher(this.shared.id, event_name, data);
493		}
494	
495		async get_data() {
496			return $state.snapshot(this.props);
497		}
498	
499		update(data: Partial<U & SharedProps>): void {
500			this.set_data(data as U & SharedProps);
501		}
502	
503		set_data(data: Partial<U & SharedProps>): void {
504			for (const key in data) {
505				// @ts-ignore
506				const value = data[key];
507				const translated = has_i18n_marker(value)
508					? this._translate_and_store(
509							this.shared_props.includes(key as keyof SharedProps)
510								? "shared"
511								: "props",
512							key,
513							value
514						)
515					: value;
516	
517				if (this.shared_props.includes(key as keyof SharedProps)) {
518					const _key = key as keyof SharedProps;
519					// @ts-ignore i'm not doing pointless typescript gymanstics
520					this.shared[_key] = translated;
521					continue;
522				}
523				// @ts-ignore
524				this.props[key] = translated;
525			}
526		}
527	
528		watch_for_change() {
529			$effect(() => {
530				if (!this.mounted) {
531					// @ts-ignore
532					this.old_value = this.props.value;
